import json, html
from pathlib import Path
SP = Path(__file__).parent
EX = json.load(open(SP / "exemplars-b64.json"))
LV = json.load(open(SP / "leaves-b64.json"))
LEAVES_JSON = json.dumps(LV["regions"])

# ---- the register: what each class IS, how a reader decides, and what ruling it needs ----
# status: existing | proposed | nonpage | subkind
C = [
 # A. existing text classes
 ("MT","Main text","existing","The body: scripture verses, or the prose of a prelim. The densest, most regular block of roman type; its left edge is a hard line of aligned line-starts.","Find the aligned left edge; it is the largest regular block. On verse pages the numeral column hugs one side of it.","Does a multi-paragraph prose prelim count as ONE block or one per paragraph? (NT-1582-B_0009)"),
 ("MN","Marginal note","existing","Text outside the measure in the fore-edge margin, in a smaller fount. 106 of 392 regions; the most common class by far.","Smaller fount, outside the measure, aligned to a body line. Read a few words: prose summary, italic citation, or a variant reading.","Sub-kinds below (§D) need a ruling: one class with an attribute, or several classes?"),
 ("RH","Running head","existing","The headline: book or section name in spaced caps, centred above the measure.","Centred over the measure, spaced caps, one line. Read it: it names the book.","Is the OUTER topical headline ('Sacrifices for', 'numbered.', 'Creation.', 'Twelue tribes') RH, MN, or its own class? Gold says MN on 0412; I read RH. Six more instances since."),
 ("PN","Page number","existing","Arabic numeral at the outer top corner. Decides recto/verso.","Top corner, outer side, 1–4 digits alone. Recto → right, verso → left.","On prelims the number may be absent (0009) or hand-inked (0007 '7', 1136 '1124'). Treat hand-inked as PN or MS?"),
 ("VN","Verse number","existing","Thin column of numerals hugging one edge of the measure, one per verse, monotone.","Column of 1–2 digit numerals at the measure edge; check monotone. Side depends on setting and recto/verso.","None — but the cascade never separates it from MT (missed on every scripture leaf)."),
 ("CH","Chapter head","existing","'CHAP. XXVIII.' centred, small caps, above an argument.","Centred, short, reads as CHAP./PSALME./ANNOTATIONS + numeral.","Sub-kinds (§D): psalm head, annotation-section head, two-line header. Same class?"),
 ("AR","Argument","existing","Italic summary under a chapter head — or, at book level, an entire italic page (0344, 1134, 1136).","Italic fount, follows a head, summarises. Read the first words: 'The Prophet describeth…'.","Chapter-level and book-level argument: one class or two?"),
 ("DC","Drop capital","existing","The initial opening a chapter or book: 2-line typographic, 6–8-line woodcut, or two-sort 'VV'.","Large glyph at the top-left of a body block, body text set beside it.","Sub-kinds (§D) — typographic vs woodcut vs two-sort. Same class?"),
 ("SG","Gathering signature","existing","Letter formula at the foot: 'Zz', 'Wwww 3', 'a iij', '† 2'. Recto only.","Letter(s) + optional numeral, centred-ish below the last line of the measure. 0777 sets it mid-page.","Dagger-series prelim signatures ('† 2') included?"),
 ("CW","Catchword","existing","The next page's first word, set right-aligned below the last line.","Single word/syllable at the foot right; may be hyphenated ('ANNO-'). 0119's is off the scan.","None. Missed 4/5 in round 1 by the cascade."),
 ("??","Abstain with cause","existing","A region the reader sees but the inventory cannot name, or a blank area reported as blank.","Never force. Name the cause.","Blank lower page (5 leaves) — is 'blank' its own class or a ?? cause?"),
 # B. proposed text classes
 ("AN","Annotation body","proposed","Commentary prose in smaller type, lemma-led paragraphs. On 12 of 35 leaves; the pipeline files every one as MT.","Smaller body fount than scripture, no verse numbers, paragraphs open with an italic lemma ending in ']'.","ACCEPT / MERGE into MT / REJECT"),
 ("LM","Lemma","proposed","The quoted verse words that open an annotation: '9. Svvete sauour.]'. Italic, verse number, closing bracket.","Italic run at a paragraph start, ends in ']'. The anchor that links AN to the verse.","Region, or an attribute of AN?"),
 ("IG","Interleaved gloss","proposed","Italic gloss lines set BETWEEN roman verse lines inside the measure (Psalter). Letter-keyed.","Fount alternates roman/italic line by line within one column; italic lines carry superscript letters.","ACCEPT — a paragraph detector shreds these leaves (0024: 1 of 13 agree)"),
 ("GK","Gloss-key column","proposed","Lettered notes 'a … b … c …' in a margin column that the IG letters point to. Left on 0022/0024, RIGHT on 0035.","Margin column whose entries begin with single letters in sequence.","Own class, or MN with an attribute?"),
 ("BT","Book / section title","proposed","'THE BOOKE OF GENESIS', 'THE ARGVMENT OF THE BOOKE OF ESTHER', 'THE THIRD PART OF THE OLD TESTAMENT'. Display caps, 1–4 lines, below an ornament.","Larger than RH, multi-line, follows an ornament or a rule, names a book or part.","Include the lower-case subtitle ('The argument of Sapiential Bookes.') and the index letter-head 'C'?"),
 ("HD","Display heading","proposed","Title of a prelim document: 'TO THE RIGHT VVELBELOVED ENGLISH READER…', 'Censura trium Theologorum…'.","Multi-line display type at the head of a prelim; not a book name.","Merge into BT?"),
 ("CR","Chapter running-head","proposed","'CHA. III.' in the headline, NT setting only. Sits at the GUTTER side; PN at the fore-edge.","Headline, outer or inner corner, reads CHA. + numeral.","ACCEPT — or attribute of RH?"),
 ("IX","Index entries","proposed","Two equal columns of alphabetical entries with page refs ('A PARTICVLAR TABLE').","Two columns of equal width, hanging indents, lines end in numerals.","ACCEPT / treat as MT with a two-column layout flag?"),
 ("TB","Table","proposed","Ruled chronological table: header row, vertical rules, cells with dates, names, prose.","Vertical rules; text aligned in cells; a header row between double rules.","ACCEPT; needs TH/TC sub-structure"),
 ("FN","End marker","proposed","'FINIS.' / 'THE END OF THE FIRST TOME.' Centred, spaced caps, followed by blank.","Centred short caps line after the last text, nothing but blank or ornament below.","ACCEPT / merge into CH?"),
 ("AT","Attestation block","proposed","Signatory lines on the Censura: NAME in caps + italic title, three entries.","Caps name + italic office, stacked, after a prose block.","ACCEPT / merge into MT?"),
 # C. non-text and non-page
 ("OR","Ornament","nonpage","Headpiece / tailpiece / type-ornament band / woodcut. Contains no text. Marks book and section boundaries.","Dense non-glyph ink, symmetric, at the head or below the last line.","ACCEPT — needed so it is not OCR'd, and because it is a boundary landmark"),
 ("RL","Printed rule","nonpage","Horizontal or vertical rules: annotation/chapter separators, table rules, frame rules.","Thin straight ink, page-wide or column-tall.","ACCEPT — the rule on NT leaves IS the AN/MT boundary"),
 ("MS","Manuscript marks","nonpage","Reader's pen strokes, ticks, hand-inked foliation. Not type.","Irregular ink, not aligned to any line, brown/thin.","ACCEPT (exclude from OCR)"),
 ("XP","Off-page","nonpage","Scanner surround, book edge, gutter shadow — pixels that are not the leaf.","Black or dark border, page edge visible inside it.","ACCEPT — move 1: 'what part of this image is the leaf?'"),
 ("AP","Adjacent-page bleed","nonpage","The facing leaf's ink visible at the edge of the scan.","Text at the extreme edge, cut off, often mirrored orientation of the margin.","ACCEPT (exclude)"),
 ("ST","Show-through","nonpage","Ghost of the verso's ink, mirror-image, faint.","Faint mirrored text, usually the verso's running head.","ACCEPT (exclude)"),
 ("CT","Crop truncation","nonpage","Text runs off the scan edge; the catchword or last line is not on the image.","Line cut mid-word at the image boundary.","ACCEPT — a leaf flag, not a region"),
]

SUB = [
 ("MN sub-kinds", "summary note (roman prose) · citation note (italic refs 'Io. 4. v. 24.') · alternate reading ('* or, manah sacrifice.') · Greek note (κατατομή) · dating gloss ('Anno. 1568.')", "One class + attribute, or five classes? The transcription treats them differently."),
 ("CH sub-kinds", "chapter head · psalm head ('PSALME. III.') · annotation-section head ('ANNOTATIONS. PSALME. III.', or two lines)", "Same class?"),
 ("DC sub-kinds", "2-line typographic initial · 6–8-line woodcut initial · two-sort 'VV' initial", "Same class? Detection differs completely."),
 ("RH vs topical headline", "'NVMERI.' (book name, centre) vs 'Sacrifices for' / 'numbered.' / 'Creation.' (topical, outer). Gold on 0412 says MN; I say RH.", "Ruling needed; 7 instances."),
 ("AR chapter vs book", "3-line italic under CHAP. vs a 50-line italic page", "Same class?"),
 ("MT one vs many", "A prose prelim in four paragraphs: one block or four?", "Ruling needed for 0009, 0028, 0007."),
 ("Blank", "Lower page blank on 1085, 1136, 0028, 0564, 0777", "Own class, or a '??' cause?"),
]

STATUS_LABEL = {"existing":"in the inventory today","proposed":"proposed — text","nonpage":"proposed — not text"}

def esc(s): return html.escape(s, quote=True)

def plate(cls):
    recs = EX.get(cls, [])
    out = []
    for r in recs[:2]:
        out.append(f'''<figure class="ex">
  <img class="crop" tabindex="0" role="button" data-leaf="{esc(r["leaf"])}" data-box="{",".join(str(v) for v in r["box"])}" src="data:image/jpeg;base64,{r["crop"]}" alt="{esc(cls)} exemplar on {esc(r["leaf"])} — open full leaf">
  <div class="loc"><img tabindex="0" role="button" data-leaf="{esc(r["leaf"])}" data-box="{",".join(str(v) for v in r["box"])}" src="data:image/jpeg;base64,{r["thumb"]}" alt="locator for {esc(r["leaf"])} — open full leaf">
    <figcaption><b>{esc(r["leaf"])}</b><br>{esc(r["why"])}</figcaption></div>
</figure>''')
    return "\n".join(out)

rows = []
for code, name, status, what, how, ruling in C:
    n = len(EX.get(code, []))
    rows.append(f'''
<section class="cls {status}" id="c-{esc(code).replace('?','q')}" data-code="{esc(code)}">
  <header class="ch">
    <span class="code">{esc(code)}</span>
    <h3>{esc(name)}</h3>
    <span class="status">{esc(STATUS_LABEL[status])}</span>
  </header>
  <div class="body">
    <div class="text">
      <p class="what">{esc(what)}</p>
      <p class="how"><span class="lbl">how a reader decides</span>{esc(how)}</p>
      <p class="ruling"><span class="lbl">ruling needed</span>{esc(ruling)}</p>
      <div class="verdict" role="group" aria-label="verdict for {esc(code)}">
        <label><input type="radio" name="v-{esc(code)}" value="accept"> accept</label>
        <label><input type="radio" name="v-{esc(code)}" value="merge"> merge</label>
        <label><input type="radio" name="v-{esc(code)}" value="rename"> rename</label>
        <label><input type="radio" name="v-{esc(code)}" value="reject"> reject</label>
        <input type="text" class="note" placeholder="note, or merge target / new name" aria-label="note for {esc(code)}">
      </div>
    </div>
    <div class="plates">{plate(code)}</div>
  </div>
</section>''')

subrows = "\n".join(f'''<tr><td class="k">{esc(a)}</td><td>{esc(b)}</td><td class="q">{esc(c)}</td>
<td><select aria-label="ruling for {esc(a)}" data-sub="{esc(a)}"><option value="">—</option><option>one class + attribute</option><option>separate classes</option><option>other (note)</option></select>
<input type="text" class="note" data-sub-note="{esc(a)}" placeholder="note" aria-label="note for {esc(a)}"></td></tr>''' for a,b,c in SUB)

